(window.webpackJsonp=window.webpackJsonp||[]).push([[17],{370:function(t,e){"use strict";e.__esModule=!0,e.default={render:function(){return this.$createElement("div",{staticClass:"theme-default-content content__default lab-wide",domProps:{innerHTML:"\n<div class=\"lab-content join-page\">\r\n<h1 id=\"join-mi2\"><a href=\"#join-mi2\" class=\"header-anchor\">#</a> Join MI² Lab</h1>\r\n<section class=\"join-hero\"><p class=\"eyebrow\">Graduate studies · Research training · Collaboration</p><h2>Build clinically grounded medical intelligence</h2><p>We welcome students who want to connect rigorous computation with real medical questions. The lab combines foundational algorithm research, multimodal medical data, and translational collaborations with hospitals.</p><div class=\"profile-actions\"><a class=\"button-secondary\" href=\"#application-path\">How to apply</a></div></section>\n\n<h2 id=\"why-mi2\"><a href=\"#why-mi2\" class=\"header-anchor\">#</a> Why MI² Lab</h2>\n<div class=\"value-grid\"><article><strong>Problem-driven research practice</strong><p>Start from a concrete medical question and work through problem formulation, method design, experimental validation, and research communication.</p></article><article><strong>Proven mentorship</strong><p>Research published across TPAMI, TMI, Medical Image Analysis, JBHI, Pattern Recognition, MICCAI, and other leading venues.</p></article><article><strong>Clinical connection</strong><p>Work with medical images and clinical collaborators to turn algorithms into measurable biomarkers and decision support.</p></article></div>\n\r\n<h2 id=\"candidate-profile\"><a href=\"#candidate-profile\" class=\"header-anchor\">#</a> Who We Are Looking For</h2>\r\n<div class=\"candidate-layout\"><ul class=\"check-list\"><li>Applicants for master’s, regular Ph.D., or direct Ph.D. programs at Nanjing University.</li><li>Background in computer science, biomedical engineering, medical imaging, clinical medicine, applied mathematics, or a related discipline.</li><li>Clear interest in medical imaging, computer vision, multimodal large models, medical agents, or medicine–engineering research.</li><li>Strong programming and mathematical foundations; publication or open-source experience is a plus.</li><li>Reliable, collaborative, proactive in communication, and ready for sustained research.</li></ul><aside><p class=\"eyebrow\">Also welcome</p><p>Research assistants, interns, visiting students, and collaborators from hospitals, imaging centers, and life-science research groups.</p></aside></div>\n\r\n<h2 id=\"admissions\"><a href=\"#admissions\" class=\"header-anchor\">#</a> Admissions</h2>\r\n<div class=\"info-table\"><div><span>Affiliation</span><strong><a class=\"institution-link\" href=\"https://bme.nju.edu.cn/\" target=\"_blank\" rel=\"noopener noreferrer\">School of Biomedical Engineering, Nanjing University (Suzhou Campus)</a></strong></div><div><span>Advisor</span><strong>Jiong Zhang</strong></div><div><span>Programs</span><strong>Master’s · Regular Ph.D. · Direct Ph.D.</strong></div><div><span>Openings</span><strong>Subject to the annual plans of Nanjing University and the school</strong></div></div>\n\r\n<h2 id=\"application-path\"><a href=\"#application-path\" class=\"header-anchor\">#</a> Application Path</h2>\r\n<div class=\"steps\"><div><span>1</span><h3>Explore the fit</h3><p>Review the lab’s recent publications and projects to identify a concrete topic of interest.</p></div><div><span>2</span><h3>Prepare materials</h3><p>Send a concise introduction, CV, transcript, research interests, and links to representative papers, code, or projects if available.</p></div><div><span>3</span><h3>Contact the lab</h3><p>Email <a href=\"mailto:lixiang.cog@smail.nju.edu.cn\">lixiang.cog@smail.nju.edu.cn</a>. Formal applications follow the current notices of Nanjing University and the school.</p></div></div>\n<div class=\"team-callout application-callout\"><div><p class=\"eyebrow\">Start a conversation</p><h3>Tell us what medical problem you want to solve.</h3><p>Specific positions and timelines depend on the university’s annual admissions plan.</p></div><a class=\"button-primary\" href=\"mailto:lixiang.cog@smail.nju.edu.cn\">Email the PI</a></div>\n</div>"}})}}}}]);
